import re
import requests
from bs4 import BeautifulSoup

class URLPreview:
    def __init__(self, url):
        self.url = url
## COMPLETE CODE HERE

    def get_title(self):
        if self.regex.match(self.url):
            return "Search Engine Result"
        else:
            try:
                page = requests.get(self.url)
                soup = BeautifulSoup(page.content, 'html.parser')
                title = soup.title.string.strip()
                return title if len(title) < 50 else title[:50] + "..."
            except:
                return "Error getting title"

    def get_description(self):
        try:
            page = requests.get(self.url)
            soup = BeautifulSoup(page.content, 'html.parser')
            desc = soup.find('meta', {'name':'description'})['content'].strip()
            return desc if len(desc) < 100 else desc[:100] + "..."
        except:
            return "No description found"

    def get_image(self):
        try:
            page = requests.get(self.url)
            soup = BeautifulSoup(page.content, 'html.parser')
            image = soup.find('meta', {'property':'og:image'})['content'].strip()
            return image if len(image) < 100 else image[:100] + "..."
        except:
            return "No image found"
