import re

class LinkShortener:
    def __init__(self):
        self.url_map = {}

    def shorten(self, url):
## COMPLETE CODE HERE
        if not regex.match(url):
            raise ValueError("Invalid URL")

        # Generate shortened URL
        shortened = self.generate_short_url(url)

        # Store mapping
        self.url_map[shortened] = url

        return shortened

    def expand(self, shortened_url):
        if shortened_url in self.url_map:
            return self.url_map[shortened_url]
        else:
            raise ValueError("Invalid shortened URL")

    def generate_short_url(self, url):
        # Generate random string
        random_string = generate_random_string()

        # Return shortened URL
        return f"https://short.ly/{random_string}"

def generate_random_string():
    import random
    import string
    letters = string.ascii_lowercase
    return ''.join(random.choice(letters) for i in range(6))

def main():
    shortener = LinkShortener()
    url = input("Enter URL to shorten: ")
    shortened = shortener.shorten(url)
    print(f"Shortened URL: {shortened}")
    expanded = shortener.expand(shortened)
    print(f"Expanded URL: {expanded}")

if __name__ == "__main__":
    main()
