# Code for a password strength meter with custom rules

import string
import itertools

def check_sequential_digits(password):
    """Check if password contains 3+ sequential digits like 123"""
    for i in range(len(password)-2):
        if password[i].isdigit() and password[i+1].isdigit() and password[i+2].isdigit():
            return True
    return False

def check_sequential_letters(password):
    """Check if password contains 3+ sequential letters like abc"""
    for i in range(len(password)-2):
        if password[i].isalpha() and password[i+1].isalpha() and password[i+2].isalpha():
            return True
    return False 

def check_common_passwords(password):
    """Check password against a list of common passwords"""
    with open("common_passwords.txt") as f:
        common_passwords = f.read().split()

    return password in common_passwords

def generate_guesses(password):
    # Generate password guesses based on rules
    guesses = []

    if check_sequential_digits(password):
        guesses.append(password.replace(password[1], "x")) # replace middle digit with x

    if check_sequential_letters(password):
        guesses.append(password.replace(password[2], "1")) # replace last letter with 1

    guesses.append(password.swapcase()) # try swapped case
    guesses.append(password[::-1]) # try reversing
    guesses.append(password + "123") # try appending some digits

    return guesses

if __name__ == "__main__":
    # Example usage
    password = input("Enter a password: ")

    # Check simple rules
    if len(password) < 8:
        print("Password must be at least 8 characters")
    elif check_common_passwords(password):
        print("That's a common password. Try something else.") 
