    else:
        # Check using guess generator
        guesses = list(generate_guesses(password))
        if len(guesses) < 10:
            print(f"{len(guesses)} similar passwords found. Good password!")
        else:
            print(f"{len(guesses)} similar passwords found. Try a stronger password.")
